settings.custom_code:
{% assign wedge_tables = product.metafields.custom.wedge_table.value %}

{% if wedge_tables %}
  <style>
    .wedge-specs { margin-top: 32px; }

    .wedge-specs__table-wrap { overflow-x: auto; }

    .wedge-specs table {
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
      min-width: 900px;
    }

    .wedge-specs th {
      background: #000;
      color: #fff;
      padding: 10px 12px;
      text-align: left;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.03em;
      font-size: 12px;
      white-space: nowrap;
    }

    .wedge-specs td {
      padding: 10px 12px;
      border-bottom: 1px solid #e5e5e5;
      white-space: nowrap;
    }

    .wedge-specs tbody tr:nth-child(even) { background: #f7f7f7; }
  </style>

  {% for wedge_table in wedge_tables %}
    <section class="wedge-specs">
      <div class="wedge-specs__table-wrap">
        <table>
          <thead>
            <tr>
              <th>Loft</th>
              <th>Grind</th>
              <th>Bounce</th>
              <th>Grooves</th>
              <th>Hand</th>
              <th>Lie</th>
              <th>Length</th>
              <th>SW</th>
            </tr>
          </thead>
          <tbody>
            {% for row in wedge_table.rows.value %}
              <tr>
                <td>{{ row.loft }}</td>
                <td>{{ row.grind }}</td>
                <td>{{ row.bounce }}</td>
                <td>{{ row.grooves }}</td>
                <td>{{ row.hand }}</td>
                <td>{{ row.lie }}</td>
                <td>{{ row.length }}</td>
                <td>{{ row.sw }}</td>
              </tr>
            {% endfor %}
          </tbody>
        </table>
      </div>
    </section>
  {% endfor %}
{% endif %}

{% assign shaft_tables = product.metafields.custom.wedge_shaft_table.value %}

{% if shaft_tables %}
  <style>
    .shaft-specs { margin-top: 32px; }

    .shaft-specs__title {
      font-weight: 700;
      letter-spacing: 0.02em;
      margin-bottom: 12px;
      text-transform: uppercase;
      text-align: center;
    }

    .shaft-specs__table-wrap { overflow-x: auto; }

    .shaft-specs table {
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
      min-width: 520px;
    }

    .shaft-specs th {
      background: #000;
      color: #fff;
      padding: 10px 12px;
      text-align: left;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.03em;
      font-size: 12px;
      white-space: nowrap;
    }

    .shaft-specs td {
      padding: 10px 12px;
      border-bottom: 1px solid #e5e5e5;
      white-space: nowrap;
    }

    .shaft-specs tbody tr:nth-child(even) { background: #f7f7f7; }

    .shaft-specs tbody td:first-child { font-weight: 700; }

    .shaft-specs__footnote {
      margin-top: 16px;
      font-size: 13px;
      line-height: 1.4;
      color: #555;
      text-align: center;
    }

    .shaft-specs__media { margin-top: 16px; }

    .shaft-specs__image-wrap {
      width: 100%;
      max-width: 900px;
      margin: 0 auto;
    }

    .shaft-specs__image {
      width: 100%;
      height: auto !important;
      max-width: 100%;
      object-fit: contain !important;
      display: block;
    }
  </style>

  {% for shaft_table in shaft_tables %}
    <section class="shaft-specs">

      {% if shaft_table.shaft != blank %}
        <h2 class="shaft-specs__title">{{ shaft_table.shaft }}</h2>
      {% endif %}

      <div class="shaft-specs__table-wrap">
        <table>
          <thead>
            <tr>
              <th>Flex</th>
              <th>Weight</th>
              <th>Butt Diameter</th>
              <th>Spin</th>
              <th>Launch</th>
            </tr>
          </thead>
          <tbody>
            {% for row in shaft_table.rows.value %}
              <tr>
                <td>{{ row.flex }}</td>
                <td>{{ row.weight }}</td>
                <td>{{ row.butt_diameter }}</td>
                <td>{{ row.spin }}</td>
                <td>{{ row.launch }}</td>
              </tr>
            {% endfor %}
          </tbody>
        </table>
      </div>

      {% if shaft_table.image %}
        <div class="shaft-specs__media">
          <div class="shaft-specs__image-wrap">
            {{ shaft_table.image
              | image_url: width: 1400
              | image_tag: loading: 'lazy', alt: shaft_table.shaft, class: 'shaft-specs__image'
            }}
          </div>
        </div>
      {% endif %}

      {% if shaft_table.footnote != blank %}
        <div class="shaft-specs__footnote">{{ shaft_table.footnote }}</div>
      {% endif %}

    </section>
  {% endfor %}
{% endif %}

